"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[46603],{46603:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/one-of-them-killed-her.png\\"\\n          title=\\"둘 중 누군가 그녀를 죽였다\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"현대문학\\"\\n          publishedDate=\\"2009-06-25\\"\\n          isbn=\\"9788972754381\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n범인의 이름이 밝혀지지 않은 채, ```가가``` 형사의 모호한 <mark>뭐, 그냥 둘 중 한 명이 그녀를 죽였다고 해 두죠</mark>라는 말로 작품이 끝난다.  \\n이 작품이 출간되었을 당시, 범인이 누구냐는 독자들의 문의 전화로 출판사가 마비되었을 정도라 한다.  \\n<br>\\n작가는 독자에게 탐정과 동일한 정보와 단서를 텍스트를 통해 제공받는다.  \\n<br>\\n작품 속에서 <mark>믿었던 사람에게 배신을 당했다</mark>라는 인물의 대사가 나온다.  \\n이 대사는 사건의 서막을 알리는 동시에, 범인의 정체를 밝히지 않은 작가의 배신을 암시하는 거 아닐까?  \\n<br>\\n사건 현장의 단서들은 두 개의 독립적인 살해 계획에 의해 오염되어 해석에 극도의 혼란을 가져온다.  \\n<br>\\n작가의 이야기를 수동적으로 소비하는 독자의 관계에서 ```작가는 문제를 제시하고 독자는 그것을 해결한다```라는 새로운 관계를 정립해준 흥미로운 작품인 것 같다."}')}}]);